
import numpy as np

DESCRIPTION = ("Exact forward. Stage 1 is one-dimensional: because W_x is a single vector, h1 = relu(x1*Wx) = xp*max(Wx,0) + xn*max(-Wx,0) "
 "with xp = relu(x1), xn = relu(-x1) - the whole first state is fixed by the sign of x1 and its magnitude. Each later step adds the "
 "new input along Wx, mixes the previous state with W_h and clamps: h_t = relu(x_t*Wx + h_{t-1} W_h). Only the seven class-score "
 "differences d_j = score_j - score_0 matter for the decision, so the readout needs no baseline column (and one of its weights is "
 "irrelevant and set to zero).")

WX = np.array([-0.20729784667491913, 0.0301608107984066, -1.2026538848876953, -0.15057843923568726, -0.46720558404922485, 0.003241136437281966, 0.6188392639160156, 0.003973902203142643])
